CREATE OR REPLACE FUNCTION public.admin_cancel_order(p_order_type text,p_order_id uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_inventory() THEN RAISE EXCEPTION 'admin access required'; END IF; IF p_order_type='shop' THEN UPDATE public.orders SET status='cancelled',updated_at=now() WHERE id=p_order_id; ELSIF p_order_type='subscription' THEN UPDATE public.product_subscriptions SET status='cancelled',updated_at=now() WHERE id=p_order_id; ELSIF p_order_type='booking' THEN UPDATE public.tbl_bookings SET status='cancelled',updated_at=now() WHERE id=p_order_id; ELSE RAISE EXCEPTION 'unsupported order type'; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'order not found'; END IF; END $$;
GRANT EXECUTE ON FUNCTION public.admin_cancel_order(text,uuid) TO authenticated;
